import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const require=createRequire(process.env.HOME+'/.local/share/omgithub-playwright/package.json');
const {chromium}=require('playwright');
const cfg=JSON.parse(readFileSync(process.env.HOME+'/.local/share/omgithub-playwright/linux.json','utf8'));
const browser=await chromium.launch(cfg.browser.launchOptions);
try {
 for (const viewport of [{width:1440,height:900},{width:390,height:844}]) {
  const page=await browser.newPage({viewport,isMobile:viewport.width<500,hasTouch:viewport.width<500});
  const errors=[];page.on('pageerror',e=>errors.push(e.message));
  await page.goto('http://127.0.0.1:4173',{waitUntil:'load'});await page.waitForFunction(()=>window.__threeArena);await page.evaluate(()=>document.querySelector('#deploy').click());await page.waitForTimeout(100);
  console.log(viewport.width,await page.evaluate(()=>({playing:window.__gameState.playing,toast:document.querySelector('#toast').className,camera:window.__threeArena.camera.parent===window.__threeArena.scene})),errors);
  if(viewport.width<500)await page.screenshot({path:'/tmp/opencode/captures-final/active-mobile.png'});
  await page.close();
 }
} finally {await browser.close()}
